Definition wk_frame (s0 s1 s2 s3 s4 : word) : list cell :=
  [C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 (wz ATHUNK_RET)].

(* [comment removed for export] *)
Definition ra_frame (j : list byte) (w0 w1 : Z) (s5 : word) (P verb MP nm ver rar : Z) : list cell :=
  [CB 8 j; C8 (wz w0); C8 (wz w1); C8 s5; C8 (wz (P + 80)); C8 (wz verb); C8 (wz MP); C8 (wz nm); C8 (wz ver); C8 (wz rar)].

Definition req_frames (m : mem) (sp : word) (ra s0 s1 s2 s3 s4 s5 : word) (j : list byte) (w0 w1 P verb MP nm ver rar : Z) : Prop :=
  rw_cells bsegs m (bv_unsigned sp + -16) [C8 (wz 0); C8 ra]
  /\ rw_cells bsegs m (bv_unsigned sp + -64) (wk_frame s0 s1 s2 s3 s4)
  /\ rw_cells bsegs m (bv_unsigned sp + -144) (ra_frame j w0 w1 s5 P verb MP nm ver rar).

(* [comment removed for export] *)
Definition req_pure (sp : word) (P MP TP lo : Z) (mbs tbs : list byte) : Prop :=
  1 <= Z.of_nat (length mbs) < 2^26 /\ 1 <= Z.of_nat (length tbs) < 2^26
  /\ MP + Z.of_nat (length mbs) <= aceil /\ TP + Z.of_nat (length tbs) <= aceil
  /\ P + 256 <= aceil /\ P mod 8 = 0 /\ aceil <= lo /\ lo + ONREQ_STACK <= bv_unsigned sp
  /\ bv_unsigned sp mod 16 = 0.

