    /\ munch [(lo, bv_unsigned sp); (P + O_PR_HDR, P + O_PR_HDR + 40)]%Z m1 m2 /\ wmono bsegs m1 m2 /\ mem_inv bsegs m2
    /\ stk bsegs m2 lo (bv_unsigned sp)
