  rw_cells bsegs m1 (bv_unsigned sp + -64) (wk_frame s0v s1v s2v s3v s4v) ->
  rw_cells bsegs m1 (P + O_PR_HDR) (HdrCells h) -> 0 <= hv_ver h < 2^32 ->
