(* [comment removed for export] *)
(* [comment removed for export] *)
Definition req_seg1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P verb MP TP ver lo : Z) (mbs tbs : list byte) (h : hdrv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m1 (j : list byte),
    ms' = MS (mkR (wz ART_RET1) (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz (P + 144)) (wz (P + 152))
                  (wz (Z.of_nat (length tbs) + 1)) a1 a2 a3 a4 a5 a6 a7
                  (wz MP) (wz (Z.shiftr (P + 152) 3 + 2147450880)) (wz 2147450880) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (wz AOPNEW) fc None m1 (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (P + O_PR_USED, P + O_PR_USED + 1)]%Z m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
    /\ stk bsegs m1 lo (bv_unsigned sp + -144)
    /\ req_frames m1 sp ra s0 s1 s2 s3 s4 s5 j TP (Z.of_nat (length tbs)) P verb MP (Z.of_nat (length mbs)) ver AWK_RET_RT
    /\ rw_cells bsegs m1 (P + O_PR_USED) [C1 (b8 1)]
    /\ rw_cells bsegs m1 (P + O_PR_HDR) (HdrCells h)
    /\ bytes_at bsegs m1 MP mbs /\ bytes_at bsegs m1 TP tbs.

Definition req_seg1_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P verb MP TP ver lo : Z) (mbs tbs : list byte) (h : hdrv),
  a0 = wz P -> a1 = wz verb -> a2 = wz MP -> a3 = wz (Z.of_nat (length mbs)) -> a4 = wz TP -> a5 = wz (Z.of_nat (length tbs)) ->
  a6 = wz ver ->
  rw_cells bsegs m (P + O_PR_USED) [C1 (b8 0)] ->
  rw_cells bsegs m (P + O_PR_HDR) (HdrCells h) -> hdr_empty h ->
  bytes_at bsegs m MP mbs -> bytes_at bsegs m TP tbs ->
  (MP + Z.of_nat (length mbs) <= P \/ P + 256 <= MP) -> (TP + Z.of_nat (length tbs) <= P \/ P + 256 <= TP) ->
  stk bsegs m lo (bv_unsigned sp) ->
  req_pure sp P MP TP lo mbs tbs -> 0 <= verb < 2^32 -> (ver = 10 \/ ver = 11) ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  0 <= P -> aapp P 256 -> accessible m P 256 -> ACONST m ->
  evt bsegs (req_seg1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P verb MP TP ver lo mbs tbs h m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_ON_REQUEST_IMPL) fc None m (seg_rom bsegs)).

